/* ============================================
   GreenBean Coffee — Global Styles
   ============================================ */

/* CSS Variables */
:root {
  --primary-green: #00824A;
  --dark-forest: #32462F;
  --warm-cream: #F3CEA1;
  --cream-light: #FFF8F0;
  --cream-bg: #FDF6ED;
  --white: #FFFFFF;
  --black: #1A1A1A;
  --gray-900: #2D2D2D;
  --gray-700: #4A4A4A;
  --gray-500: #737373;
  --gray-300: #BDBDBD;
  --gray-100: #F2F2F2;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.12);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;
  --transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Reset & Base */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: var(--gray-900);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: 'DM Sans', 'Inter', sans-serif;
  font-weight: 700;
  line-height: 1.2;
  color: var(--dark-forest);
}

/* Utility Classes */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  font-size: 0.95rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  transition: var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--primary-green);
  color: var(--white);
}
.btn-primary:hover {
  background: #006B3D;
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-secondary {
  background: var(--white);
  color: var(--primary-green);
  border: 2px solid var(--primary-green);
}
.btn-secondary:hover {
  background: var(--primary-green);
  color: var(--white);
}

.btn-dark {
  background: var(--dark-forest);
  color: var(--white);
}
.btn-dark:hover {
  background: #243324;
}

/* ============================================
   Header & Navigation
   ============================================ */
.header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: var(--white);
  border-bottom: 1px solid var(--gray-100);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: 'DM Sans', sans-serif;
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--primary-green);
}

.logo-icon {
  width: 36px;
  height: 36px;
  background: var(--primary-green);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 1rem;
}

.nav-main {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-main a {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--gray-700);
  transition: var(--transition);
  position: relative;
}

.nav-main a:hover,
.nav-main a.active {
  color: var(--primary-green);
}

.nav-main a.active::after {
  content: '';
  position: absolute;
  bottom: -24px;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--primary-green);
  border-radius: 2px 2px 0 0;
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

.nav-actions a {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--gray-700);
  transition: var(--transition);
}

.nav-actions a:hover {
  color: var(--primary-green);
}

.nav-actions .btn {
  padding: 8px 18px;
  font-size: 0.85rem;
}

.mobile-menu-btn {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}

.mobile-menu-btn span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--gray-700);
  border-radius: 2px;
  transition: var(--transition);
}

/* ============================================
   Cookie Banner
   ============================================ */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 2000;
  background: var(--dark-forest);
  color: var(--white);
  padding: 20px 0;
  transform: translateY(0);
  transition: transform 0.4s ease;
}

.cookie-banner.hidden {
  transform: translateY(100%);
}

.cookie-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}

.cookie-text h3 {
  color: var(--warm-cream);
  font-size: 1.1rem;
  margin-bottom: 4px;
}

.cookie-text p {
  font-size: 0.9rem;
  opacity: 0.9;
}

.cookie-actions {
  display: flex;
  gap: 12px;
  flex-shrink: 0;
}

.cookie-actions button {
  padding: 10px 20px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.9rem;
  transition: var(--transition);
}

.cookie-btn-settings {
  background: transparent;
  color: var(--warm-cream);
  border: 1px solid var(--warm-cream);
}
.cookie-btn-settings:hover {
  background: var(--warm-cream);
  color: var(--dark-forest);
}

.cookie-btn-agree {
  background: var(--primary-green);
  color: var(--white);
}
.cookie-btn-agree:hover {
  background: #006B3D;
}

/* ============================================
   Hero Section
   ============================================ */
.hero {
  position: relative;
  min-height: 600px;
  display: flex;
  align-items: center;
  background: linear-gradient(135deg, var(--cream-bg) 0%, var(--warm-cream) 100%);
  overflow: hidden;
}

.hero-bg-pattern {
  position: absolute;
  inset: 0;
  opacity: 0.06;
  background-image: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%2300824A' fill-opacity='1'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
}

.hero-inner {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
  padding: 80px 24px;
}

.hero-content h1 {
  font-size: clamp(2.5rem, 5vw, 4rem);
  margin-bottom: 20px;
  color: var(--dark-forest);
}

.hero-content p {
  font-size: 1.15rem;
  color: var(--gray-700);
  margin-bottom: 32px;
  max-width: 480px;
}

.hero-visual {
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-visual .placeholder-img {
  width: 100%;
  max-width: 480px;
  aspect-ratio: 1;
  border-radius: var(--radius-xl);
  background: linear-gradient(145deg, var(--primary-green), var(--dark-forest));
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 6rem;
  box-shadow: var(--shadow-lg);
}

/* ============================================
   Promo / Feature Cards
   ============================================ */
.promo-section {
  padding: 80px 0;
}

.promo-section.alt-bg {
  background: var(--cream-bg);
}

.promo-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
}

.promo-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  align-items: center;
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 40px;
  box-shadow: var(--shadow-md);
  transition: var(--transition);
}

.promo-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.promo-card.reverse {
  direction: rtl;
}

.promo-card.reverse > * {
  direction: ltr;
}

.promo-card.full-width {
  grid-template-columns: 1fr 1fr;
  grid-column: 1 / -1;
}

.promo-card .placeholder-img {
  width: 100%;
  aspect-ratio: 4/3;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, var(--warm-cream), #E8B87A);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--dark-forest);
  font-size: 3rem;
}

.promo-card h2 {
  font-size: 1.8rem;
  margin-bottom: 12px;
}

.promo-card p {
  color: var(--gray-700);
  margin-bottom: 24px;
  line-height: 1.7;
}

/* Seasonal Highlights */
.seasonal-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
}

.seasonal-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  min-height: 400px;
  display: flex;
  align-items: flex-end;
  box-shadow: var(--shadow-md);
}

.seasonal-card .placeholder-img {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 4rem;
}

.seasonal-card:nth-child(2) .placeholder-img {
  background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%);
}

.seasonal-content {
  position: relative;
  padding: 32px;
  background: linear-gradient(transparent, rgba(0,0,0,0.7));
  color: var(--white);
  width: 100%;
}

.seasonal-content h2 {
  color: var(--white);
  font-size: 1.6rem;
  margin-bottom: 8px;
}

.seasonal-content p {
  margin-bottom: 16px;
  opacity: 0.95;
}

.seasonal-content .btn {
  background: var(--white);
  color: var(--dark-forest);
}
.seasonal-content .btn:hover {
  background: var(--cream-light);
}

/* ============================================
   Footer
   ============================================ */
.footer {
  background: var(--dark-forest);
  color: var(--white);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 32px;
  margin-bottom: 48px;
}

.footer-col h4 {
  color: var(--warm-cream);
  font-size: 0.95rem;
  margin-bottom: 16px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.footer-col ul li {
  margin-bottom: 10px;
}

.footer-col ul li a {
  font-size: 0.9rem;
  opacity: 0.85;
  transition: var(--transition);
}

.footer-col ul li a:hover {
  opacity: 1;
  color: var(--warm-cream);
}

.footer-col-toggle {
  display: none;
  width: 100%;
  justify-content: space-between;
  align-items: center;
  background: none;
  border: none;
  color: var(--warm-cream);
  font-family: 'DM Sans', sans-serif;
  font-size: 0.95rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 12px 0;
  cursor: pointer;
}

.footer-col-toggle .icon {
  transition: transform 0.3s ease;
}

.footer-col.collapsed .footer-col-toggle .icon {
  transform: rotate(180deg);
}

.footer-col.collapsed .footer-col-content {
  display: none;
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
}

.footer-bottom p {
  font-size: 0.85rem;
  opacity: 0.7;
}

.social-links {
  display: flex;
  gap: 16px;
}

.social-links a {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
}

.social-links a:hover {
  background: var(--primary-green);
}

/* ============================================
   Menu Page
   ============================================ */
.menu-page {
  background: var(--cream-bg);
}

.breadcrumb {
  padding: 16px 0;
  font-size: 0.85rem;
  color: var(--gray-500);
}

.breadcrumb a:hover {
  color: var(--primary-green);
}

.menu-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: 40px;
  padding: 24px 0 64px;
}

.menu-sidebar {
  position: sticky;
  top: 96px;
  align-self: start;
}

.menu-sidebar h3 {
  font-size: 1.1rem;
  margin-bottom: 20px;
  color: var(--dark-forest);
}

.sidebar-group {
  margin-bottom: 24px;
}

.sidebar-group-title {
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: var(--gray-500);
  margin-bottom: 10px;
}

.sidebar-group ul li {
  margin-bottom: 6px;
}

.sidebar-group ul li a {
  display: block;
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  color: var(--gray-700);
  transition: var(--transition);
}

.sidebar-group ul li a:hover,
.sidebar-group ul li a.active {
  background: var(--white);
  color: var(--primary-green);
  box-shadow: var(--shadow-sm);
}

.menu-main h2 {
  font-size: 1.6rem;
  margin-bottom: 24px;
  color: var(--dark-forest);
}

.menu-category {
  margin-bottom: 48px;
}

.menu-category-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
}

.menu-category-header h3 {
  font-size: 1.3rem;
}

.menu-items-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 20px;
}

.menu-item-card {
  background: var(--white);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
}

.menu-item-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
}

.menu-item-card .placeholder-img {
  width: 100%;
  aspect-ratio: 1;
  background: linear-gradient(135deg, var(--cream-bg), var(--warm-cream));
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--dark-forest);
  font-size: 2rem;
}

.menu-item-card h4 {
  padding: 16px 16px 4px;
  font-size: 0.95rem;
}

.menu-item-card p {
  padding: 0 16px 16px;
  font-size: 0.85rem;
  color: var(--gray-500);
}

/* ============================================
   Rewards Page
   ============================================ */
.rewards-hero {
  background: linear-gradient(135deg, var(--dark-forest) 0%, #1a2e18 100%);
  color: var(--white);
  padding: 80px 0;
  text-align: center;
}

.rewards-hero h1 {
  color: var(--white);
  font-size: clamp(2rem, 4vw, 3.2rem);
  margin-bottom: 16px;
}

.rewards-hero p {
  font-size: 1.1rem;
  opacity: 0.9;
  max-width: 560px;
  margin: 0 auto 32px;
}

.how-it-works {
  padding: 80px 0;
  background: var(--white);
}

.how-it-works h2 {
  text-align: center;
  font-size: 2rem;
  margin-bottom: 48px;
}

.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.step-card {
  text-align: center;
  padding: 32px;
}

.step-number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--primary-green);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  font-weight: 700;
  margin: 0 auto 20px;
}

.step-card h3 {
  font-size: 1.2rem;
  margin-bottom: 10px;
}

.step-card p {
  color: var(--gray-700);
  font-size: 0.95rem;
}

/* Status Tiers */
.status-tiers {
  padding: 80px 0;
  background: var(--cream-bg);
}

.status-tiers h2 {
  text-align: center;
  font-size: 2rem;
  margin-bottom: 48px;
}

.tiers-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.tier-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 40px 32px;
  text-align: center;
  box-shadow: var(--shadow-md);
  transition: var(--transition);
  border-top: 4px solid var(--primary-green);
}

.tier-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-lg);
}

.tier-card.gold {
  border-top-color: #D4AF37;
}

.tier-card.reserve {
  border-top-color: #C0C0C0;
}

.tier-icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: var(--cream-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
  font-size: 1.8rem;
}

.tier-card h3 {
  font-size: 1.4rem;
  margin-bottom: 4px;
}

.tier-stars {
  font-size: 0.9rem;
  color: var(--primary-green);
  font-weight: 600;
  margin-bottom: 20px;
}

.tier-benefits {
  text-align: left;
}

.tier-benefits li {
  padding: 8px 0;
  border-bottom: 1px solid var(--gray-100);
  font-size: 0.9rem;
  color: var(--gray-700);
  display: flex;
  align-items: center;
  gap: 8px;
}

.tier-benefits li::before {
  content: '✓';
  color: var(--primary-green);
  font-weight: 700;
}

/* Redemption Levels */
.redemption-levels {
  padding: 80px 0;
  background: var(--white);
}

.redemption-levels h2 {
  text-align: center;
  font-size: 2rem;
  margin-bottom: 16px;
}

.redemption-subtitle {
  text-align: center;
  color: var(--gray-500);
  margin-bottom: 48px;
}

.redemption-tabs {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-bottom: 40px;
  flex-wrap: wrap;
}

.redemption-tab {
  padding: 12px 20px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--gray-700);
  background: var(--gray-100);
  transition: var(--transition);
  border: 2px solid transparent;
}

.redemption-tab:hover {
  background: var(--cream-bg);
}

.redemption-tab.active {
  background: var(--primary-green);
  color: var(--white);
  border-color: var(--primary-green);
}

.redemption-panel {
  display: none;
  max-width: 600px;
  margin: 0 auto;
  text-align: center;
  padding: 40px;
  background: var(--cream-bg);
  border-radius: var(--radius-lg);
}

.redemption-panel.active {
  display: block;
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.redemption-panel .star-value {
  font-size: 3rem;
  font-weight: 800;
  color: var(--primary-green);
  margin-bottom: 8px;
}

.redemption-panel h3 {
  font-size: 1.4rem;
  margin-bottom: 12px;
}

.redemption-panel p {
  color: var(--gray-700);
  margin-bottom: 8px;
}

.redemption-panel .value-tag {
  display: inline-block;
  padding: 6px 16px;
  background: var(--white);
  border-radius: var(--radius-full);
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--dark-forest);
  margin-top: 8px;
}

/* Partnerships */
.partnerships {
  padding: 80px 0;
  background: var(--cream-bg);
}

.partnerships h2 {
  text-align: center;
  font-size: 2rem;
  margin-bottom: 48px;
}

.partners-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  max-width: 800px;
  margin: 0 auto;
}

.partner-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  text-align: center;
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
}

.partner-card:hover {
  box-shadow: var(--shadow-md);
}

.partner-logo {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-md);
